        elif op == '-': return a - b
        elif op == '*': return a * b
        elif op == '/': return a // b

    def apply_precedence(tokens):
        output = []
        op_stack = []

        for token in tokens:
            if token == '(':
                op_stack.append(token)
            elif token == ')':
                while op_stack[-1] != '(':
                    output.append(op_stack.pop())
                op_stack.pop() # remove '('
            elif token in '+-*/':
                while op_stack and op_stack[-1] != '(' and precedence(op_stack[-1]) >= precedence(token):
                    output.append(op_stack.pop())
                op_stack.append(token)
            else:
                output.append(int(token))

        while op_stack:
            output.append(op_stack.pop())

        return output

    def precedence(op):
        if op in '+-': return 1
        elif op in '*/': return 2
        else: raise ValueError("Invalid operator")

