def parse_duration(s):
    """
    Convert a duration string like '1h30m', '45s', '2h5s' or '1d2h' into a total number of seconds (int).

    :param s: duration string
    :return: total number of seconds as int
    :raises ValueError: for an empty string, unknown units, a unit without a number, a number without a unit, units out of order, or repeated units
    """

    units = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
    parts = []

    i = 0
    while i < len(s):
        if s[i].isdigit():
            j = i
            while j < len(s) and s[j].isdigit():
                j += 1
            parts.append((int(s[i:j]), s[j:j+1]))
            i = j + 1
        else:
            raise ValueError("A number without a unit is found")

    if not parts:
        raise ValueError("An empty string or a unit without a number is found")

    if len(parts) != len(set(parts)):
        raise ValueError("Repeated units are found")

    parts.sort(key=lambda x: x[1])
    for i in range(len(parts) - 1):
        if parts[i][1] == parts[i + 1][1]:
            raise ValueError("Units out of order are found")

    total_seconds = 0
    for num, unit in parts:
        if unit not in units:
            raise ValueError(f"Unknown unit: {unit}")
        total_seconds += num * units[unit]

    return total_seconds
