def split_fields(line):
    fields = []
    current_field = ''
    in_quote = False
    for char in line:
        if char == '"':
            in_quote = not in_quote
        elif char == ',' and not in_quote:
            fields.append(current_field.strip('"'))
            current_field = ''
        else:
            current_field += char
    if current_field:
        fields.append(current_field.strip('"'))
    if not fields:
        fields = ['']
