def flatten(d):
    """
    Flattens nested dicts into one dict with dot-joined keys.

    Args:
        d (dict): The dictionary to flatten.

    Returns:
        dict: The flattened dictionary.
    """
    def flatten_helper(d, parent_key=""):
        result = {}
        for k, v in d.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                result.update(flatten_helper(v, new_key))
            else:
                result[new_key] = v
        return result

    return flatten_helper(d)
