def flatten(d):
    """
    Flattens nested dicts into one dict with dot-joined keys.

    Args:
    d (dict): The dictionary to be flattened.

    Returns:
    dict: The flattened dictionary.
    """
    def flatten_helper(d, prefix=''):
        result = {}
        for k, v in d.items():
            new_key = prefix + '.' + k if prefix else k
            if isinstance(v, dict):
                # Recursively flatten the nested dictionary
                flattened = flatten_helper(v, new_key)
                # Only include keys if the nested dict is not empty
                result.update({k: v for k, v in flattened.items() if v})
            else:
                result[new_key] = v
        return result

    return flatten_helper(d)
